class Solution:
    def minimumSum(self, nums1, nums2):
        first = {}
        for i, x in enumerate(nums1):
            if x not in first: first[x] = i
        ans = float('inf')
        for j, y in enumerate(nums2):
            if y in first:
                ans = min(ans, first[y] + j)
        return ans if ans != float('inf') else -1

