class Solution {
public:
    int minimumSum(vector<int>& nums1, vector<int>& nums2) {
        unordered_map<int,int> first;
        for (int i = 0; i < (int)nums1.size(); i++) if (!first.count(nums1[i])) first[nums1[i]] = i;
        int ans = INT_MAX;
        for (int j = 0; j < (int)nums2.size(); j++) {
            auto it = first.find(nums2[j]);
            if (it != first.end()) ans = min(ans, it->second + j);
        }
        return ans == INT_MAX ? -1 : ans;
    }
};

