var minimumSum = function(nums1, nums2) {
    const first = new Map();
    for (let i = 0; i < nums1.length; i++) if (!first.has(nums1[i])) first.set(nums1[i], i);
    let ans = Infinity;
    for (let j = 0; j < nums2.length; j++) {
        const fi = first.get(nums2[j]);
        if (fi !== undefined) ans = Math.min(ans, fi + j);
    }
    return ans === Infinity ? -1 : ans;
};
